#!/usr/bin/env bash

set -euo pipefail

usage() {
  cat <<'EOF'
usage: gen_llvm_config.sh [--llvm-dir DIR] [--link dynamic|static] [--output FILE]

Generate the project-specific cgo configuration used by GoALLC. DIR must use
the common LLVM payload layout:

  DIR/bin/llvm-config
  DIR/include/llvm-c
  DIR/lib

The default directory is ./llvm, the default link mode is dynamic, and the
default output is ./llvm_config_goallc_generated.go.
EOF
}

script_dir="$(cd "$(dirname "$0")" && pwd -P)"
llvm_dir="${script_dir}/llvm"
link_mode="dynamic"
output="${script_dir}/llvm_config_goallc_generated.go"

while [[ $# -gt 0 ]]; do
  case "$1" in
    --llvm-dir)
      [[ $# -ge 2 ]] || { usage >&2; exit 2; }
      llvm_dir="$2"
      shift 2
      ;;
    --link)
      [[ $# -ge 2 ]] || { usage >&2; exit 2; }
      link_mode="$2"
      shift 2
      ;;
    --output)
      [[ $# -ge 2 ]] || { usage >&2; exit 2; }
      output="$2"
      shift 2
      ;;
    -h|--help)
      usage
      exit 0
      ;;
    *)
      echo "gen_llvm_config.sh: unknown argument: $1" >&2
      usage >&2
      exit 2
      ;;
  esac
done

case "$link_mode" in
  dynamic|static) ;;
  *)
    echo "gen_llvm_config.sh: --link must be dynamic or static" >&2
    exit 2
    ;;
esac

if [[ ! -d "$llvm_dir/include/llvm-c" ]]; then
  echo "gen_llvm_config.sh: LLVM C headers not found under $llvm_dir/include" >&2
  exit 1
fi
if [[ ! -d "$llvm_dir/lib" ]]; then
  echo "gen_llvm_config.sh: LLVM library directory not found: $llvm_dir/lib" >&2
  exit 1
fi
if [[ ! -x "$llvm_dir/bin/llvm-config" ]]; then
  echo "gen_llvm_config.sh: executable llvm-config not found: $llvm_dir/bin/llvm-config" >&2
  exit 1
fi

llvm_dir="$(cd "$llvm_dir" && pwd -P)"
if [[ "$llvm_dir" == *[[:space:]#]* ]]; then
  echo "gen_llvm_config.sh: LLVM directory must not contain whitespace or '#': $llvm_dir" >&2
  exit 1
fi

llvm_config="${llvm_dir}/bin/llvm-config"
llvm_version="$("$llvm_config" --version)"
llvm_major="${llvm_version%%.*}"
if [[ "$llvm_major" != "23" ]]; then
  echo "gen_llvm_config.sh: GoALLC requires LLVM 23, found $llvm_version" >&2
  exit 1
fi

host_uname="$(uname -s)"
case "$host_uname" in
  Darwin)
    cgo_os="darwin"
    ;;
  Linux)
    cgo_os="linux"
    ;;
  *)
    echo "gen_llvm_config.sh: unsupported host: $host_uname" >&2
    exit 1
    ;;
esac

cppflags="-I${llvm_dir}/include -D__STDC_CONSTANT_MACROS -D__STDC_FORMAT_MACROS -D__STDC_LIMIT_MACROS"
if [[ "$cgo_os" == "linux" ]]; then
  cppflags="$cppflags -D_GNU_SOURCE"
fi

if [[ "$link_mode" == "dynamic" ]]; then
  if [[ "$cgo_os" == "darwin" ]]; then
    compgen -G "${llvm_dir}/lib/libLLVM*.dylib" >/dev/null ||
      { echo "gen_llvm_config.sh: libLLVM dylib not found under $llvm_dir/lib" >&2; exit 1; }
    ldflags="-L${llvm_dir}/lib -Wl,-rpath,${llvm_dir}/lib -Wl,-search_paths_first -Wl,-headerpad_max_install_names -lLLVM"
  else
    compgen -G "${llvm_dir}/lib/libLLVM*.so*" >/dev/null ||
      { echo "gen_llvm_config.sh: libLLVM shared library not found under $llvm_dir/lib" >&2; exit 1; }
    ldflags="-L${llvm_dir}/lib -Wl,-rpath,${llvm_dir}/lib -lLLVM"
  fi
else
  # The public binding exposes InitializeAllTargets and the interpreter, so
  # their archives must be present even when the host target is the only one
  # used by a particular program.
  components=(core analysis bitreader bitwriter irreader linker passes all-targets executionengine mcjit interpreter target)
  configured_libfiles="$("$llvm_config" --link-static --libfiles "${components[@]}")"
  system_libs="$("$llvm_config" --link-static --system-libs "${components[@]}")"
  if [[ " $system_libs " == *" -lzstd "* ]] && command -v pkg-config >/dev/null 2>&1; then
    zstd_libdirs="$(pkg-config --libs-only-L libzstd 2>/dev/null || true)"
    if [[ -n "$zstd_libdirs" ]]; then
      system_libs="$zstd_libdirs $system_libs"
    fi
  fi
  if [[ -z "$configured_libfiles" ]]; then
    echo "gen_llvm_config.sh: llvm-config returned no static libraries" >&2
    exit 1
  fi

  libfiles=""
  for configured_archive in $configured_libfiles; do
    archive="${llvm_dir}/lib/$(basename "$configured_archive")"
    [[ -f "$archive" ]] ||
      { echo "gen_llvm_config.sh: static LLVM archive not found: $archive" >&2; exit 1; }
    libfiles="${libfiles} ${archive}"
  done
  libfiles="${libfiles# }"

  if [[ "$cgo_os" == "darwin" ]]; then
    # llvm-config emits archives in dependency order. Pass them as direct
    # linker inputs: cgo permits archive paths, and Darwin ld consumes this
    # order without the GNU-only --start-group option.
    ldflags="$libfiles $system_libs"
  else
    ldflags="-Wl,--start-group $libfiles -Wl,--end-group $system_libs"
  fi
fi

output_dir="$(dirname "$output")"
mkdir -p "$output_dir"
tmp_output="${output}.tmp.$$"
trap 'rm -f "$tmp_output"' EXIT

cat >"$tmp_output" <<EOF
//go:build goallc

// Code generated by gen_llvm_config.sh; DO NOT EDIT.

package llvm

/*
#cgo ${cgo_os} CPPFLAGS: ${cppflags}
#cgo ${cgo_os} CXXFLAGS: -std=c++17
#cgo ${cgo_os} LDFLAGS: ${ldflags}
*/
import "C"

type run_build_sh int
EOF

mv "$tmp_output" "$output"
trap - EXIT
echo "generated $output ($link_mode LLVM: $llvm_dir)"
